        do {
            // Если контейнер у вас уже создаётся, используйте его и добавьте только строку с репозиторием.
            container = try ModelContainer(for: Quote.self)
        } catch {
            fatalError("Не удалось открыть хранилище: \(error)")
        }
        // При переходе на GRDB меняется только эта строка.
        quoteRepository = SwiftDataQuoteRepository(container: container)
    }

    var body: some Scene {
        WindowGroup {
            ContentView(quoteRepository: quoteRepository) // ваш корневой экран
        }
        .modelContainer(container)
    }
}
