import Foundation
import SwiftData

@Model
final class Book {
    var id: UUID
    var title: String
    var author: String
    var addedAt: Date

    // Covers live in separate models so fetching the library never loads image bytes.
    @Relationship(deleteRule: .cascade, inverse: \BookCoverThumbnail.book)
    var coverThumbnail: BookCoverThumbnail?

    @Relationship(deleteRule: .cascade, inverse: \BookCoverImage.book)
    var coverImage: BookCoverImage?

    init(id: UUID = UUID(), title: String, author: String, addedAt: Date = .now) {
        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
    }
}

/// Small JPEG (~15 KB) shown in the library list.
@Model
final class BookCoverThumbnail {
    var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

/// Larger JPEG (~200 KB) shown on the book screen; stored as a file outside the database.
@Model
final class BookCoverImage {
    @Attribute(.externalStorage) var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    @MainActor
    func setCover(_ cover: ProcessedCover, in context: ModelContext) {
        if let coverThumbnail {
            coverThumbnail.data = cover.thumbnail
        } else {
            let thumbnail = BookCoverThumbnail(data: cover.thumbnail)
            context.insert(thumbnail)
            coverThumbnail = thumbnail
        }

        if let coverImage {
            coverImage.data = cover.image
        } else {
            let image = BookCoverImage(data: cover.image)
            context.insert(image)
            coverImage = image
        }

        ThumbnailCache.shared.remove(for: self)
        try? context.save()
    }
}
