```swift
import Foundation
import SwiftData

@Model
final class Book {
    var id: UUID
    var title: String
    var author: String
    var addedAt: Date

    @Relationship(deleteRule: .cascade, inverse: \BookCover.book)
    var cover: BookCover?

    init(id: UUID = UUID(), title: String, author: String, addedAt: Date = .now) {
        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
    }
}

// Images live in a separate model so that fetching the library list
// does not load image bytes for every book at once.
@Model
final class BookCover {
    var id: UUID = UUID()
    @Attribute(.externalStorage) var imageData: Data = Data()
    var thumbnailData: Data = Data()
    var book: Book?

    init(imageData: Data, thumbnailData: Data) {
        self.imageData = imageData
        self.thumbnailData = thumbnailData
    }
}
