## 2. Обработка фото — `CoverImageProcessor.swift`

```swift
import UIKit

enum CoverImageProcessor {
    private static let fullMaxSide: CGFloat = 1200
    private static let thumbnailMaxSide: CGFloat = 240

    /// Heavy work: call off the main thread.
    nonisolated static func process(_ photo: UIImage) -> (full: Data, thumbnail: Data)? {
        autoreleasepool {
            let full = resized(photo, maxSide: fullMaxSide)
            let thumbnail = resized(full, maxSide: thumbnailMaxSide)
            guard let fullData = full.jpegData(compressionQuality: 0.8),
                  let thumbnailData = thumbnail.jpegData(compressionQuality: 0.7)
            else { return nil }
            return (fullData, thumbnailData)
        }
    }

    nonisolated private static func resized(_ image: UIImage, maxSide: CGFloat) -> UIImage {
        let pixelSize = CGSize(width: image.size.width * image.scale,
                               height: image.size.height * image.scale)
        let ratio = min(1, maxSide / max(pixelSize.width, pixelSize.height))
        let target = CGSize(width: (pixelSize.width * ratio).rounded(),
                            height: (pixelSize.height * ratio).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard

        // draw(in:) applies the camera orientation, so the result is always upright.
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}
```

