## 5. Блок обложки для экрана книги — `BookCoverSection.swift`

```swift
import SwiftUI
import SwiftData
import UIKit

struct BookCoverSection: View {
    let book: Book
    @Environment(\.modelContext) private var modelContext
    @State private var isCameraPresented = false
    @State private var isSaving = false
    @State private var saveFailed = false

    var body: some View {
        VStack(spacing: 12) {
            BookCoverImage(cover: book.cover)
                .overlay {
                    if isSaving { ProgressView() }
                }

            if UIImagePickerController.isSourceTypeAvailable(.camera) {
                Button(book.cover == nil ? "Сфотографировать обложку" : "Переснять обложку",
                       systemImage: "camera") {
                    isCameraPresented = true
                }
                .disabled(isSaving)
            }
        }
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                Task { await saveCover(from: photo) }
            }
            .ignoresSafeArea()
        }
        .alert("Не удалось сохранить обложку", isPresented: $saveFailed) {
            Button("OK", role: .cancel) {}
        }
    }

    private func saveCover(from photo: UIImage) async {
        isSaving = true
        defer { isSaving = false }

        let processed = await Task.detached(priority: .userInitiated) {
            CoverImageProcessor.process(photo)
        }.value
        guard let processed else {
            saveFailed = true
            return
        }

        if let oldCover = book.cover {
            modelContext.delete(oldCover)
        }
        book.cover = BookCover(imageData: processed.full, thumbnailData: processed.thumbnail)
        do {
            try modelContext.save()
        } catch {
            saveFailed = true
        }
    }
}
```

