import SwiftUI
import UIKit

/// Распакованные миниатюры в памяти: при прокрутке назад обложки появляются мгновенно.
@MainActor
final class CoverThumbnailCache {
    static let shared = CoverThumbnailCache()
    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.countLimit = 200
    }

    func image(for id: UUID) -> UIImage? {
        cache.object(forKey: id as NSUUID)
    }

    func insert(_ image: UIImage, for id: UUID) {
        cache.setObject(image, forKey: id as NSUUID)
    }
}

/// Маленькая обложка для строки списка.
struct BookCoverThumbnail: View {
    let cover: BookCover?
    var width: CGFloat = 44

    @State private var loaded: (id: UUID, image: UIImage)?

    var body: some View {
        let image = currentImage
        RoundedRectangle(cornerRadius: 4)
            .fill(.quaternary)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    Image(systemName: "book.closed")
                        .foregroundStyle(.secondary)
                }
            }
            .frame(width: width, height: width * 1.5)
            .clipShape(RoundedRectangle(cornerRadius: 4))
            .accessibilityHidden(true)
            .task(id: cover?.id) { await load() }
    }

    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.id == cover.id { return loaded.image }
        return CoverThumbnailCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover, currentImage == nil else { return }
        let id = cover.id
        let data = cover.thumbnailData

        let image = await Task.detached(priority: .userInitiated) {
            UIImage(data: data)?.preparingForDisplay()
        }.value

        guard let image, !Task.isCancelled else { return }
        CoverThumbnailCache.shared.insert(image, for: id)
        loaded = (id: id, image: image)
    }
}

/// Большая обложка для экрана книги.
struct BookCoverLargeView: View {
    let cover: BookCover?

    @State private var loaded: (id: UUID, image: UIImage)?

    var body: some View {
        Group {
            if let image = currentImage {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
                    .clipShape(RoundedRectangle(cornerRadius: 8))
                    .shadow(radius: 6, y: 3)
                    .accessibilityLabel("Обложка")
            } else {
                RoundedRectangle(cornerRadius: 8)
                    .fill(.quaternary)
                    .aspectRatio(2.0 / 3.0, contentMode: .fit)
                    .overlay {
                        if cover != nil {
                            ProgressView()
                        } else {
                            Image(systemName: "book.closed")
                                .font(.largeTitle)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .accessibilityHidden(true)
            }
        }
        .frame(maxHeight: 360)
        .task(id: cover?.id) { await load() }
    }

    /// Пока грузится большая картинка, показываем миниатюру из кэша.
    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.id == cover.id { return loaded.image }
        return CoverThumbnailCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover, loaded?.id != cover.id, let data = cover.image?.data else { return }
        let id = cover.id

        let image = await Task.detached(priority: .userInitiated) {
            UIImage(data: data)?.preparingForDisplay()
        }.value

        guard let image, !Task.isCancelled else { return }
        loaded = (id: id, image: image)
    }
}
