## 4. `CameraPicker.swift`: камера

```swift
import SwiftUI
import UIKit

struct CameraPicker: UIViewControllerRepresentable {
    let onImage: (UIImage) -> Void
    @Environment(\.dismiss) private var dismiss

    static var isAvailable: Bool {
        UIImagePickerController.isSourceTypeAvailable(.camera)
    }

    func makeUIViewController(context: Context) -> UIImagePickerController {
        let picker = UIImagePickerController()
        picker.sourceType = .camera
        picker.cameraCaptureMode = .photo
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ uiViewController: UIImagePickerController, context: Context) {}

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    @MainActor
    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate {
        let parent: CameraPicker

        init(parent: CameraPicker) {
            self.parent = parent
        }

        func imagePickerController(_ picker: UIImagePickerController,
                                   didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]) {
            if let image = info[.originalImage] as? UIImage {
                parent.onImage(image)
            }
            parent.dismiss()
        }

        func imagePickerControllerDidCancel(_ picker: UIImagePickerController) {
            parent.dismiss()
        }
    }
}
```

## 5. `BookDetailView.swift`: экран книги

Если такой экран у вас уже есть, перенесите в него: `BookCoverLargeView` с `coverMenu`, все модификаторы `.fullScreenCover`, `.photosPicker`, `.onChange`, `.alert` и функции ниже `body`.

```swift
import SwiftUI
import PhotosUI
import AVFoundation

struct BookDetailView: View {
    let book: Book

    @State private var isShowingCamera = false
    @State private var isShowingPhotoPicker = false
    @State private var photoItem: PhotosPickerItem?
    @State private var isProcessing = false
    @State private var isShowingCameraAccessAlert = false
    @State private var isShowingErrorAlert = false
    @Environment(\.openURL) private var openURL

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                BookCoverLargeView(cover: book.cover)
                    .overlay {
                        if isProcessing {
                            ProgressView().controlSize(.large)
                        }
                    }

                coverMenu

                VStack(spacing: 4) {
                    Text(book.title)
                        .font(.title2.bold())
                        .multilineTextAlignment(.center)
                    Text(book.author)
                        .foregroundStyle(.secondary)
                }
            }
            .padding()
            .frame(maxWidth: .infinity)
        }
        .navigationTitle(book.title)
        .navigationBarTitleDisplayMode(.inline)
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { image in saveCover(from: image) }
                .ignoresSafeArea()
        }
        .photosPicker(isPresented: $isShowingPhotoPicker, selection: $photoItem, matching: .images)
        .onChange(of: photoItem) { _, item in
            guard let item else { return }
            photoItem = nil
            saveCover(from: item)
        }
        .alert("Нет доступа к камере", isPresented: $isShowingCameraAccessAlert) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) {
                    openURL(url)
                }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы фотографировать обложки.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $isShowingErrorAlert) {
            Button("OK", role: .cancel) {}
        }
    }

    private var coverMenu: some View {
        Menu {
            if CameraPicker.isAvailable {
                Button("Сфотографировать", systemImage: "camera") { openCamera() }
            }
            Button("Выбрать из фото", systemImage: "photo.on.rectangle") {
                isShowingPhotoPicker = true
            }
            if book.cover != nil {
                Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                    book.removeCover()
                }
            }
        } label: {
            Label(book.cover == nil ? "Добавить обложку" : "Изменить обложку", systemImage: "camera")
        }
        .buttonStyle(.bordered)
        .disabled(isProcessing)
    }

    private func openCamera() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .denied, .restricted:
            isShowingCameraAccessAlert = true
        default:
            // При первом запуске системный запрос разрешения покажет сама камера
            isShowingCamera = true
        }
    }

    private func saveCover(from image: UIImage) {
        isProcessing = true
        Task {
            let jpegs = await CoverImageProcessor.makeCover(from: image)
            finishSaving(jpegs)
        }
    }

    private func saveCover(from item: PhotosPickerItem) {
        isProcessing = true
        Task {
            var jpegs: CoverImageData?
            if let data = try? await item.loadTransferable(type: Data.self) {
                jpegs = await CoverImageProcessor.makeCover(from: data)
            }
            finishSaving(jpegs)
        }
    }

    private func finishSaving(_ jpegs: CoverImageData?) {
        isProcessing = false
        if let jpegs {
            book.setCover(jpegs)
        } else {
            isShowingErrorAlert = true
        }
    }
}
```

