## 2. `CoverStore.swift`: хранение и сжатие

```swift
import UIKit

/// Хранит обложки файлами: большая версия для экрана книги, миниатюра — для списка.
/// Это actor: сжатие, запись и чтение идут не на главном потоке.
actor CoverStore {
    static let shared = CoverStore()

    /// Длинная сторона большой версии, px.
    private let fullMaxPixels: CGFloat = 1600
    /// Длинная сторона миниатюры, px. Строка списка 44×66 pt на экране 3x — это 132×198 px.
    private let thumbnailMaxPixels: CGFloat = 300

    private let directory: URL

    private init() {
        directory = URL.applicationSupportDirectory
            .appending(path: "Covers", directoryHint: .isDirectory)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    }

    // MARK: Запись

    func saveCover(_ photo: UIImage, for bookID: UUID) throws {
        let full = downscaled(photo, maxPixels: fullMaxPixels)
        let thumbnail = downscaled(full, maxPixels: thumbnailMaxPixels)

        guard let fullData = full.heicData() ?? full.jpegData(compressionQuality: 0.8),
              let thumbnailData = thumbnail.jpegData(compressionQuality: 0.8)
        else { throw CocoaError(.fileWriteUnknown) }

        try fullData.write(to: fullURL(for: bookID), options: .atomic)
        try thumbnailData.write(to: thumbnailURL(for: bookID), options: .atomic)
    }

    func deleteCover(for bookID: UUID) {
        try? FileManager.default.removeItem(at: fullURL(for: bookID))
        try? FileManager.default.removeItem(at: thumbnailURL(for: bookID))
    }

    // MARK: Чтение (сразу декодируем, чтобы не тормозить прокрутку)

    func loadThumbnail(for bookID: UUID) -> UIImage? {
        UIImage(contentsOfFile: thumbnailURL(for: bookID).path(percentEncoded: false))?
            .preparingForDisplay()
    }

    func loadFullImage(for bookID: UUID) -> UIImage? {
        UIImage(contentsOfFile: fullURL(for: bookID).path(percentEncoded: false))?
            .preparingForDisplay()
    }

    // MARK: Уборка

    /// Удаляет обложки книг, которых больше нет.
    /// Свежие файлы (моложе 10 минут) не трогаем — на случай, если книга ещё не успела сохраниться.
    func removeOrphans(keeping existingIDs: Set<UUID>) {
        let fileManager = FileManager.default
        guard let files = try? fileManager.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: [.contentModificationDateKey]
        ) else { return }

        let threshold = Date.now.addingTimeInterval(-600)
        for file in files {
            guard let id = UUID(uuidString: String(file.lastPathComponent.prefix(36))),
                  !existingIDs.contains(id) else { continue }
            let modified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]))?
                .contentModificationDate ?? .distantPast
            if modified < threshold {
                try? fileManager.removeItem(at: file)
            }
        }
    }

    // MARK: Внутреннее

    private func fullURL(for bookID: UUID) -> URL {
        directory.appending(path: "\(bookID.uuidString)-cover.heic")
    }

    private func thumbnailURL(for bookID: UUID) -> URL {
        directory.appending(path: "\(bookID.uuidString)-thumb.jpg")
    }

    /// Уменьшает картинку и заодно «выпрямляет» её (фото с камеры обычно хранится повёрнутым).
    private func downscaled(_ image: UIImage, maxPixels: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let ratio = min(1, maxPixels / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * ratio).rounded(),
                            height: (pixelHeight * ratio).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard // не 16 бит на канал — вдвое меньше памяти

        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}
```

## 3. `BookCoverView.swift`: показ обложки и кэш миниатюр

```swift
import SwiftUI
import UIKit

/// Кэш уже декодированных миниатюр. iOS сама очищает его при нехватке памяти.
@MainActor
final class CoverCache {
    static let shared = CoverCache()

    private let cache = NSCache<NSString, UIImage>()

    private init() {
        cache.totalCostLimit = 40 * 1024 * 1024 // ~40 МБ
    }

    func image(forKey key: String) -> UIImage? {
        cache.object(forKey: key as NSString)
    }

    func insert(_ image: UIImage, forKey key: String) {
        let bytes = Int(image.size.width * image.scale * image.size.height * image.scale * 4)
        cache.setObject(image, forKey: key as NSString, cost: bytes)
    }
}

struct BookCoverView: View {
    enum Style { case thumbnail, full }

    let bookID: UUID
    let version: Date?
    let style: Style

    @State private var image: UIImage?

    init(bookID: UUID, version: Date?, style: Style = .thumbnail) {
        self.bookID = bookID
        self.version = version
        self.style = style
        // Если миниатюра уже в памяти — показываем сразу, без мигания заглушки.
        if style == .thumbnail, let version {
            _image = State(initialValue: CoverCache.shared.image(forKey: Self.cacheKey(bookID, version)))
        }
    }

    var body: some View {
        content
            .task(id: version) { await load() }
    }

    @ViewBuilder
    private var content: some View {
        switch style {
        case .thumbnail:
            RoundedRectangle(cornerRadius: 4)
                .fill(.quaternary)
                .overlay {
                    if let image {
                        Image(uiImage: image).resizable().scaledToFill()
                    } else {
                        Image(systemName: "book.closed").foregroundStyle(.secondary)
                    }
                }
                .clipShape(.rect(cornerRadius: 4))
                .accessibilityHidden(true)
        case .full:
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
                    .clipShape(.rect(cornerRadius: 8))
                    .accessibilityLabel("Обложка")
            } else {
                RoundedRectangle(cornerRadius: 8)
                    .fill(.quaternary)
                    .aspectRatio(2 / 3, contentMode: .fit)
                    .overlay { ProgressView() }
            }
        }
    }

    private func load() async {
        guard let version else {
            image = nil
            return
        }
        let key = Self.cacheKey(bookID, version)
        if style == .thumbnail, let cached = CoverCache.shared.image(forKey: key) {
            image = cached
            return
        }

        let loaded: UIImage?
        if style == .thumbnail {
            loaded = await CoverStore.shared.loadThumbnail(for: bookID)
        } else {
            loaded = await CoverStore.shared.loadFullImage(for: bookID)
        }
        guard !Task.isCancelled else { return }

        if style == .thumbnail, let loaded {
            CoverCache.shared.insert(loaded, forKey: key)
        }
        image = loaded
    }

    private static func cacheKey(_ bookID: UUID, _ version: Date) -> String {
        "\(bookID.uuidString)-\(version.timeIntervalSinceReferenceDate)"
    }
}
