                    .padding()
                    .background(.regularMaterial, in: .rect(cornerRadius: 12))
            }
        }
        .fullScreenCover(isPresented: $showCamera) {
            CameraPicker { photo in
                Task { await saveCover(photo) }
            }
            .ignoresSafeArea()
        }
        .alert("Нет доступа к камере", isPresented: $showCameraDenied) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы фотографировать обложки.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $showSaveError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз. Если не поможет — проверьте, есть ли свободное место на iPhone.")
        }
    }

    @ViewBuilder
    private var cover: some View {
        if book.coverUpdatedAt != nil {
            BookCoverView(bookID: book.id, version: book.coverUpdatedAt, style: .full)
                .frame(maxWidth: 280)
                .shadow(color: .black.opacity(0.2), radius: 8, y: 4)
        } else {
            Button {
                Task { await openCamera() }
            } label: {
                VStack(spacing: 8) {
                    Image(systemName: "camera").font(.largeTitle)
                    Text("Сфотографировать обложку").font(.callout)
                }
                .frame(width: 200, height: 300)
                .background(.quaternary, in: .rect(cornerRadius: 8))
            }
            .buttonStyle(.plain)
            .disabled(isSaving)
        }
    }

    private func openCamera() async {
        // На симуляторе камеры нет — сразу открываем фотоальбом.
        guard UIImagePickerController.isSourceTypeAvailable(.camera) else {
            showCamera = true
            return
        }
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            showCamera = true
        case .notDetermined:
            if await AVCaptureDevice.requestAccess(for: .video) {
                showCamera = true
            } else {
                showCameraDenied = true
            }
        default:
            showCameraDenied = true
        }
    }

    private func saveCover(_ photo: UIImage) async {
        isSaving = true
        defer { isSaving = false }
        do {
            try await CoverStore.shared.saveCover(photo, for: book.id)
            book.coverUpdatedAt = .now // меняется «версия» — список и экран обновятся сами
        } catch {
            showSaveError = true
        }
    }

    private func removeCover() async {
        book.coverUpdatedAt = nil
        await CoverStore.shared.deleteCover(for: book.id)
    }
