Если у вас уже есть экран списка, достаточно поставить `BookRow(book: book)` на место текущей строки. Удаление (`delete`) стоит взять из этого примера: оно сразу стирает и файлы обложки.

```swift
import SwiftUI
import SwiftData

struct LibraryView: View {
    @Query(sort: \Book.addedAt, order: .reverse) private var books: [Book]
    @Environment(\.modelContext) private var modelContext

    var body: some View {
        NavigationStack {
            List {
                ForEach(books) { book in
                    NavigationLink(value: book) {
                        BookRow(book: book)
                    }
                }
                .onDelete(perform: delete)
            }
            .navigationTitle("Библиотека")
            .navigationDestination(for: Book.self) { book in
                BookDetailView(book: book)
            }
        }
    }

    private func delete(at offsets: IndexSet) {
        for index in offsets {
            let book = books[index]
            let id = book.id
            modelContext.delete(book)
            Task { await CoverStore.shared.deleteCover(for: id) }
        }
    }
}

