import SwiftUI
import CoreTransferable
import UniformTypeIdentifiers

// MARK: - CSV-файл с историей чтения

/// CSV-файл с историей чтения для ShareLink.
/// Текст файла собирается только тогда, когда пользователь выбрал, куда его отправить.
struct ReadingHistoryCSV: Transferable, Sendable {

    /// Копия нужных полей сессии. Экспорт выполняется в фоне,
    /// поэтому исходные объекты из фона не трогаем.
    struct Row: Sendable {
        let startedAt: Date
        let duration: TimeInterval
        let timeZoneIdentifier: String
        let bookTitle: String
        let bookAuthor: String
    }

    let rows: [Row]
    let separator: Character
    let fileName: String

    init(sessions: [ReadingSession], locale: Locale = .current, now: Date = .now) {
        rows = sessions
            .map {
                Row(
                    startedAt: $0.startedAt,
                    duration: $0.duration,
                    timeZoneIdentifier: $0.timeZoneIdentifier,
                    bookTitle: $0.bookTitle,
                    bookAuthor: $0.bookAuthor
                )
            }
            .sorted { $0.startedAt < $1.startedAt }
        separator = Self.separator(for: locale)
        fileName = "История чтения \(Self.dayField(now, in: .current)).csv"
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { csv in
            // Отдельная папка на каждый экспорт: имя файла остаётся красивым, а файлы не конфликтуют.
            let folder = URL.temporaryDirectory
                .appending(path: UUID().uuidString, directoryHint: .isDirectory)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let fileURL = folder.appending(path: csv.fileName, directoryHint: .notDirectory)
            try csv.makeData().write(to: fileURL, options: .atomic)
            return SentTransferredFile(fileURL)
        }
    }

    // MARK: Содержимое файла

    /// UTF-8 с BOM: без BOM Excel показывает кириллицу нечитаемыми символами.
    func makeData() -> Data {
        Data([0xEF, 0xBB, 0xBF]) + Data(makeText().utf8)
    }

    func makeText() -> String {
        let separator = String(separator)
        let header = ["Начало", "Длительность, мин", "Название", "Автор"].map(Self.textField)
        var lines = [header.joined(separator: separator)]
        for row in rows {
            let fields = [
                Self.dateTimeField(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                Self.minutesField(row.duration),
                Self.textField(row.bookTitle),
                Self.textField(row.bookAuthor),
            ]
            lines.append(fields.joined(separator: separator))
        }
        // RFC 4180: строки разделяются CRLF.
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    // MARK: Поля

    /// Excel использует «;», если в регионе дробная часть отделяется запятой (Россия, Европа),
    /// и «,» в остальных случаях (США, Великобритания).
    static func separator(for locale: Locale) -> Character {
        locale.decimalSeparator == "," ? ";" : ","
    }

    /// Текст всегда в кавычках, кавычки внутри удваиваются.
    /// Поэтому запятые, точки с запятой и кавычки в названиях ничего не ломают.
    static func textField(_ value: String) -> String {
        var text = String(value.map { $0.isNewline || $0 == "\t" ? " " : $0 })
            .trimmingCharacters(in: .whitespaces)
        // Иначе Excel примет такое значение за формулу.
        if let first = text.first, "=+-@".contains(first) {
            text = "'" + text
        }
        return "\"" + text.replacing("\"", with: "\"\"") + "\""
    }

    /// Формат «2026-10-25 21:40» Excel и Numbers распознают как дату и время при любом языке системы.
    static func dateTimeField(_ date: Date, timeZoneIdentifier: String) -> String {
        let timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        let c = Calendar(identifier: .gregorian).dateComponents(in: timeZone, from: date)
        return String(
            format: "%04d-%02d-%02d %02d:%02d",
            c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0
        )
    }

    static func dayField(_ date: Date, in timeZone: TimeZone) -> String {
        let c = Calendar(identifier: .gregorian).dateComponents(in: timeZone, from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }

    /// Целое число минут без десятичного разделителя, чтобы не зависеть от региональных настроек.
    static func minutesField(_ duration: TimeInterval) -> String {
        guard duration.isFinite, duration > 0 else { return "0" }
        // Ограничение защищает от падения на заведомо ошибочных значениях.
        return String(Int((min(duration, 1_000_000_000) / 60).rounded()))
    }
}

