```swift
import SwiftUI
import UniformTypeIdentifiers

/// Экспорт истории чтения в CSV для Excel и Numbers.
/// Используется через ShareLink: файл создаётся только в момент, когда пользователь нажимает «Поделиться».
struct ReadingHistoryCSV: Transferable, Sendable {

    /// Копия данных сессии. Не зависит от того, как устроен ReadingSession (в том числе от SwiftData).
    struct Row: Sendable {
        let startedAt: Date
        let duration: TimeInterval
        let timeZone: TimeZone
        let title: String
        let author: String
    }

    static let header = ["Начало", "Длительность (мин)", "Название", "Автор"]

    let rows: [Row]
    let locale: Locale
    let createdAt: Date

    init(sessions: [ReadingSession], locale: Locale = .current, createdAt: Date = .now) {
        self.rows = sessions
            .map { session in
                Row(
                    startedAt: session.startedAt,
                    duration: session.duration,
                    timeZone: TimeZone(identifier: session.timeZoneIdentifier) ?? .current,
                    title: session.bookTitle,
                    author: session.bookAuthor
                )
            }
            .sorted { $0.startedAt < $1.startedAt }
        self.locale = locale
        self.createdAt = createdAt
    }

    // MARK: - Transferable

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            SentTransferredFile(try export.writeTemporaryFile())
        }
    }

    // MARK: - Файл

    var fileName: String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.dateFormat = "yyyy-MM-dd"
        return "История чтения \(formatter.string(from: createdAt)).csv"
    }

    func writeTemporaryFile() throws -> URL {
        // Отдельная папка на каждый экспорт: имя файла остаётся красивым и ничего не перезаписывается.
        let folder = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let url = folder.appendingPathComponent(fileName)
        try Data(csvString().utf8).write(to: url, options: .atomic)
        return url
    }

    // MARK: - CSV

    func csvString() -> String {
        // Если в регионе пользователя дробная часть отделяется запятой (Россия, Европа),
        // Excel ожидает разделитель «;». Иначе (США, Великобритания) — «,».
        let usesCommaDecimal = (locale.decimalSeparator ?? ".") == ","
        let delimiter = usesCommaDecimal ? ";" : ","

        var dateFormatters: [String: DateFormatter] = [:]
        var lines = [Self.header.map(Self.quoted).joined(separator: delimiter)]

        for row in rows {
            let formatter: DateFormatter
            if let cached = dateFormatters[row.timeZone.identifier] {
                formatter = cached
            } else {
                formatter = Self.makeDateFormatter(timeZone: row.timeZone)
                dateFormatters[row.timeZone.identifier] = formatter
            }

            let fields = [
                formatter.string(from: row.startedAt),
                Self.minutes(row.duration, usesCommaDecimal: usesCommaDecimal),
                Self.quoted(row.title),
                Self.quoted(row.author),
            ]
            lines.append(fields.joined(separator: delimiter))
        }

        // BOM в начале: без него Excel показывает кириллицу «кракозябрами».
        // CRLF: стандартный перевод строки для CSV.
        return "\u{FEFF}" + lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Дата и время по часам того места, где читали. Формат, который Excel и Numbers распознают как дату.
    private static func makeDateFormatter(timeZone: TimeZone) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = timeZone
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        return formatter
    }

    /// Минуты с точностью до десятых, без разделителей тысяч, с десятичным знаком как у пользователя.
    private static func minutes(_ duration: TimeInterval, usesCommaDecimal: Bool) -> String {
        let seconds = duration.isFinite ? max(0, duration) : 0
        let value = (seconds / 60 * 10).rounded() / 10
        let text = value.formatted(
            .number
                .precision(.fractionLength(0...1))
                .grouping(.never)
                .locale(Locale(identifier: "en_US_POSIX"))
        )
        return usesCommaDecimal ? text.replacingOccurrences(of: ".", with: ",") : text
    }

    /// Текстовое поле всегда берётся в двойные кавычки, а кавычки внутри удваиваются (стандарт CSV).
    /// Поэтому запятые, точки с запятой, кавычки и переносы строк в названиях ничего не ломают.
    private static func quoted(_ text: String) -> String {
        var value = text
        // Защита от формул: Excel выполняет ячейку, которая начинается с = + - @, как формулу.
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }
}

