import SwiftUI
import UIKit

typealias BookID = String

actor CoverCache {
    static let shared = CoverCache()

    // One entry per book: in-flight task while loading, finished task afterwards.
    private var covers: [BookID: Task<UIImage, any Error>] = [:]

    func cover(for id: BookID) async throws -> UIImage {
        if let existing = covers[id] {
            return try await existing.value
        }

        // Detached so the slow disk read never runs on this actor, regardless of project isolation settings.
        let task = Task.detached { try await loadCoverFromDisk(id: id) }
        covers[id] = task

        do {
            return try await task.value
        } catch {
            // Allow a retry on the next request instead of caching the failure.
            covers[id] = nil
            throw error
        }
    }
}

struct BookCoverView: View {
    let bookID: BookID

    private enum CoverState {
        case loading
        case loaded(UIImage)
        case failed
    }

    @State private var state: CoverState = .loading

    var body: some View {
        Group {
            switch state {
            case .loading:
                ProgressView()
            case .loaded(let image):
                Image(uiImage: image).resizable().scaledToFit()
            case .failed:
                Image(systemName: "book.closed").resizable().scaledToFit().foregroundStyle(.secondary)
            }
        }
        .task(id: bookID) {
            state = .loading
            let image = try? await CoverCache.shared.cover(for: bookID)
            // The view may have switched to another book while this cover was loading.
            guard !Task.isCancelled else { return }
            state = image.map(CoverState.loaded) ?? .failed
        }
    }
}
```

На любом экране обложка выводится так: `BookCoverView(bookID: book.id)`.

## Как это устроено

- **Защита от одновременных запросов.** `CoverCache` — это `actor`, то есть он выполняет запросы строго по одному. Первый запрос на книгу запускает загрузку и сразу записывает её в общий список. Второй экран, спросив ту же книгу, находит в списке уже начатую загрузку и ждёт её же. Так с диска читается один раз.
- **Хранилище в памяти.** В списке остаётся и уже законченная загрузка. Следующий запрос сразу получает готовую картинку, отдельное хранилище не нужно.
- **Ошибка не запоминается.** Если чтение с диска не удалось, запись удаляется. При следующем показе экран попробует загрузить обложку ещё раз.
- **Чтение идёт в фоне.** Загрузка вынесена в отдельную фоновую задачу. Медленное чтение с диска не тормозит интерфейс и не задерживает выдачу других, уже загруженных обложек.
- **Закрытый экран не мешает другим.** Если экран закрыли во время загрузки, загрузка всё равно доходит до конца. Картинка остаётся в памяти, и другие экраны, которые её ждут, тоже её получат.

## Что исправлено после проверки

1. **Чужая обложка.** Если на одном и том же месте книга сменилась во время загрузки, могла появиться обложка предыдущей книги. Теперь при смене книги сначала показывается индикатор загрузки. Результат загрузки для старой книги отбрасывается.
2. **Вечный индикатор.** Если обложку не удалось прочитать, индикатор загрузки крутился бесконечно. Теперь в этом случае показывается значок книги.

## Допущения

- Идентификатор книги — строка. Если в проекте он другого типа, например `UUID` или `Int`, достаточно поменять одну строку `typealias BookID = String`.
- `loadCoverFromDisk(id:)` — обычная функция, которую можно вызвать из любого места кода. Если внутри она сама делает тяжёлую работу в главном потоке, интерфейс может подтормаживать. Мой кеш это исправить не может.
- Загруженные обложки хранятся в памяти, пока приложение не закроют. Иначе нельзя гарантировать, что одна обложка не будет прочитана дважды. Цена — при очень большом числе книг (сотни и больше крупных обложек за один запуск) может вырасти потребление памяти. Если это когда-нибудь станет проблемой, можно разрешить системе выгружать старые обложки, но тогда их иногда придётся читать с диска повторно.
- Если обложка не загрузилась, экран не пробует сам загрузить её снова, пока он открыт. Новая попытка будет, когда экран откроют заново.

## Код

```swift
import SwiftUI
import UIKit

/// Type of the book identifier. Change it if your ids are not strings (e.g. UUID or Int).
typealias BookID = String

/// Shared cover cache. Guarantees that each cover is read from disk at most once at a time,
/// no matter how many screens request it concurrently.
actor CoverCache {
    static let shared = CoverCache()

    /// Loaded covers. NSCache frees memory automatically when the system is low on it.
    private let images = NSCache<NSString, UIImage>()

    /// Covers that are being read from disk right now.
    private var inFlight: [BookID: Task<UIImage, Error>] = [:]

    init(maxImages: Int = 200) {
        images.countLimit = maxImages
    }

    func cover(for id: BookID) async throws -> UIImage {
        let key = "\(id)" as NSString

        // 1. Already in memory.
        if let image = images.object(forKey: key) {
            return image
        }

        // 2. Someone is already loading it: wait for the same result.
        if let task = inFlight[id] {
            return try await task.value
        }

        // 3. Nobody is loading it yet: start the only disk read for this id.
        // Detached so the slow disk work does not run on the cache actor.
        let task = Task.detached(priority: .userInitiated) {
            try await loadCoverFromDisk(id: id)
        }
        inFlight[id] = task
        defer { inFlight[id] = nil }

        let image = try await task.value
        images.setObject(image, forKey: key)
        return image
    }
}

/// Example of using the cache from a screen.
struct BookCoverView: View {
    let bookID: BookID
    @State private var image: UIImage?

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                ProgressView()
            }
        }
        .task(id: bookID) {
            image = nil
            image = try? await CoverCache.shared.cover(for: bookID)
        }
    }
}
```

## Ключевые решения

- **Кеш сделан как `actor`.** Swift сам не даёт двум потокам одновременно менять данные кеша, поэтому код проходит строгую проверку Swift 6 без обходных приёмов.
- **Загрузка с диска происходит один раз.** Первый экран, которому нужна обложка, запускает чтение с диска и записывает его в список «загружается сейчас». Если в это время обложку попросит второй экран, он не начнёт новое чтение, а подождёт то же самое и получит ту же картинку.
- **Чтение с диска идёт отдельно от кеша.** Пока одна обложка грузится медленно, другие экраны получают уже загруженные обложки сразу.
- **Ошибки не запоминаются.** Если чтение не удалось, ошибку получат все экраны, которые ждали эту обложку. При следующем запросе загрузка начнётся заново.
- **Память ограничена.** Кеш хранит до 200 обложек и сам освобождает место, когда системе не хватает памяти. Убранная из памяти обложка при следующем запросе снова загрузится с диска.
- **Уход с экрана не отменяет общую загрузку.** Если один экран закрылся, загрузка продолжается для остальных, кто её ждёт.

## Допущения

1. Id книги — это строка. Если в проекте id другого типа (UUID, число), достаточно поменять одну строку: `typealias BookID = String`.
2. `loadCoverFromDisk(id:)` — обычная функция, доступная из любого места проекта, с таким же названием и параметром, как в вашем описании.
3. Лимит в 200 обложек выбран наугад. Его можно поменять: `CoverCache(maxImages: ...)`.
4. Если обложка не загрузилась, `BookCoverView` показывает индикатор загрузки. Отдельную картинку для ошибки я не делал.
