### 1. `ReadingSessionShared.swift`
Подключается к двум таргетам: приложение и расширение DeviceActivityMonitor.

```swift
import DeviceActivity
import Foundation
import ManagedSettings

struct ReadingSession: Codable, Equatable, Sendable {
    let id: UUID
    let startDate: Date
    let endDate: Date

    var minutes: Int {
        Int((endDate.timeIntervalSince(startDate) / 60).rounded())
    }
}

struct ReadingSessionState: Codable, Sendable {
    var activeSession: ReadingSession?
    /// Credited reading minutes keyed by local calendar day, "yyyy-MM-dd".
    var minutesByDay: [String: Int] = [:]
    /// Set when a session finishes; the app consumes it so Slumpy can announce it.
    var hasPendingFinishAnnouncement = false

    func minutesRead(on date: Date) -> Int {
        minutesByDay[Self.dayKey(for: date)] ?? 0
    }

    static func dayKey(for date: Date) -> String {
        let day = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", day.year ?? 0, day.month ?? 0, day.day ?? 0)
    }
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("readingSession") }
}

/// State shared through the App Group. Both the app and the DeviceActivityMonitor
/// extension write it, so every access goes through NSFileCoordinator.
enum ReadingSessionStore {
    static let appGroupID = "group.com.example.slumpy" // TODO: real App Group ID

    private static var fileURL: URL {
        guard let container = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: appGroupID) else {
            fatalError("App Group \(appGroupID) is not configured for this target")
        }
        return container.appending(path: "reading-session.json")
    }

    static func read() -> ReadingSessionState {
        var state: ReadingSessionState?
        NSFileCoordinator().coordinate(readingItemAt: fileURL, options: [], error: nil) { url in
            state = load(from: url)
        }
        return state ?? load(from: fileURL)
    }

    @discardableResult
    static func update<T>(_ change: (inout ReadingSessionState) -> T) -> T {
        var result: T?
        NSFileCoordinator().coordinate(writingItemAt: fileURL, options: .forMerging, error: nil) { url in
            result = apply(change, at: url)
        }
        // Coordination failure is rare; an uncoordinated write is better than a lost one.
        return result ?? apply(change, at: fileURL)
    }

    static func begin(_ session: ReadingSession) {
        update { $0.activeSession = session }
    }

    /// Returns false when the session was already finished elsewhere or replaced by a newer one.
    @discardableResult
    static func finish(sessionID: UUID) -> Bool {
        update { state in
            guard let session = state.activeSession, session.id == sessionID else { return false }
            state.activeSession = nil
            state.minutesByDay[ReadingSessionState.dayKey(for: session.endDate), default: 0] += session.minutes
            state.hasPendingFinishAnnouncement = true
            return true
        }
    }

    static func consumeFinishAnnouncement() -> Bool {
        update { state in
            let pending = state.hasPendingFinishAnnouncement
            state.hasPendingFinishAnnouncement = false
            return pending
        }
    }

    private static func apply<T>(_ change: (inout ReadingSessionState) -> T, at url: URL) -> T {
        var state = load(from: url)
        let result = change(&state)
        if let data = try? JSONEncoder().encode(state) {
            try? data.write(to: url, options: .atomic)
        }
        return result
    }

    private static func load(from url: URL) -> ReadingSessionState {
        guard let data = try? Data(contentsOf: url),
              let state = try? JSONDecoder().decode(ReadingSessionState.self, from: data) else {
            return ReadingSessionState()
        }
        return state
    }
}

enum ReadingSessionMonitor {
    private static let activityPrefix = "readingSession."

    static func sessionID(for activity: DeviceActivityName) -> UUID? {
        guard activity.rawValue.hasPrefix(activityPrefix) else { return nil }
        return UUID(uuidString: String(activity.rawValue.dropFirst(activityPrefix.count)))
    }

    /// The extension's intervalDidEnd ends the session while the app is suspended or killed.
    static func start(for session: ReadingSession) throws {
        stopAll()
        // DeviceActivity rejects intervals shorter than 15 minutes. Only the end matters,
        // so a shorter session gets its interval start moved into the past.
        let intervalStart = min(session.startDate, session.endDate.addingTimeInterval(-15 * 60))
        let components: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        let schedule = DeviceActivitySchedule(
            intervalStart: Calendar.current.dateComponents(components, from: intervalStart),
            intervalEnd: Calendar.current.dateComponents(components, from: session.endDate),
            repeats: false
        )
        try DeviceActivityCenter().startMonitoring(
            DeviceActivityName(activityPrefix + session.id.uuidString),
            during: schedule
        )
    }

    static func stopAll() {
        let center = DeviceActivityCenter()
        let names = center.activities.filter { sessionID(for: $0) != nil }
        // An empty list would stop every activity the app monitors, not none.
        guard !names.isEmpty else { return }
        center.stopMonitoring(names)
    }
}
```

