import DeviceActivity
import ManagedSettings

final class DeviceActivityMonitorExtension: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingSessionMonitor.sessionID(for: activity) else { return }
        // false: the app already finished this session or a newer one replaced it,
        // so the current shields are not this session's to remove.
        guard ReadingSessionStore.finish(sessionID: sessionID) else { return }
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }
}
