### 5. `ReadingSessionController.swift`
Таргет: приложение.

```swift
import ActivityKit
import FamilyControls
import Foundation
import ManagedSettings
import Observation
import SwiftUI

@MainActor
@Observable
final class ReadingSessionController {
    private(set) var activeSession: ReadingSession?
    private(set) var minutesReadToday = 0
    /// What Slumpy should say; the UI sets it back to nil once shown.
    var slumpyMessage: String?

    private var finishTask: Task<Void, Never>?

    func start(minutes: Int, blocking selection: FamilyActivitySelection) throws {
        guard activeSession == nil else { return }
        let now = Date.now
        let session = ReadingSession(id: UUID(), startDate: now, endDate: now.addingTimeInterval(TimeInterval(minutes) * 60))

        // Saved before monitoring restarts: stopping an old monitor may wake the extension,
        // which must then see this session instead of finishing the old one.
        ReadingSessionStore.begin(session)
        do {
            try ReadingSessionMonitor.start(for: session)
        } catch {
            ReadingSessionStore.update { $0.activeSession = nil }
            throw error
        }

        let store = ManagedSettingsStore(named: .readingSession)
        let categories = selection.categoryTokens
        store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        store.shield.applicationCategories = categories.isEmpty ? nil : .specific(categories)
        store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
        store.shield.webDomainCategories = categories.isEmpty ? nil : .specific(categories)

        startLiveActivity(for: session)
        activeSession = session
        scheduleInAppFinish(for: session)
    }

    func scenePhaseChanged(to phase: ScenePhase) {
        if phase == .active {
            Task { await refresh() }
        } else {
            // Off screen the monitor extension finishes the session.
            finishTask?.cancel()
        }
    }

    private func refresh() async {
        if let session = ReadingSessionStore.read().activeSession, session.endDate <= .now {
            ReadingSessionStore.finish(sessionID: session.id)
        }

        let state = ReadingSessionStore.read()
        activeSession = state.activeSession
        minutesReadToday = state.minutesRead(on: .now)

        if let session = state.activeSession {
            scheduleInAppFinish(for: session)
        } else {
            // Repeating this is harmless and covers the extension never having run (e.g. phone was off).
            ManagedSettingsStore(named: .readingSession).clearAllSettings()
            ReadingSessionMonitor.stopAll()
        }

        if ReadingSessionStore.consumeFinishAnnouncement() {
            slumpyMessage = "Сессия окончена"
        }

        await endFinishedLiveActivities()
    }

    private func scheduleInAppFinish(for session: ReadingSession) {
        finishTask?.cancel()
        finishTask = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, session.endDate.timeIntervalSinceNow)))
            guard !Task.isCancelled else { return }
            await self?.refresh()
        }
    }

    private func startLiveActivity(for session: ReadingSession) {
        let attributes = ReadingSessionAttributes(sessionID: session.id, startDate: session.startDate, endDate: session.endDate)
        // staleDate lets the widget show "session over" on time even if the app never runs again.
        let content = ActivityContent(state: ReadingSessionAttributes.ContentState(isFinished: false), staleDate: session.endDate)
        // The session works without a Live Activity (the user may have turned them off).
        _ = try? Activity.request(attributes: attributes, content: content, pushType: nil)
    }

    private func endFinishedLiveActivities() async {
        for activity in Activity<ReadingSessionAttributes>.activities where activity.attributes.sessionID != activeSession?.id {
            await activity.end(
                ActivityContent(state: ReadingSessionAttributes.ContentState(isFinished: true), staleDate: nil),
                dismissalPolicy: .immediate
            )
        }
    }
}
```

