### 1. `Shared/ReadingSessionCore.swift` — targets: приложение + DeviceActivityMonitor

```swift
import DeviceActivity
import Foundation
import ManagedSettings
import os

enum AppGroup {
    // Replace with the App Group identifier already configured in the project.
    static let id = "group.com.example.slumpy"
}

extension DeviceActivityName {
    static var readingSession: Self { Self("readingSession") }
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("readingSession") }
}

struct ReadingSession: Codable, Sendable {
    let id: UUID
    let startDate: Date
    let endDate: Date
    let minutes: Int
}

/// Session state shared by the app and the DeviceActivityMonitor extension.
/// Either process may finish the session; a file lock guarantees the minutes are credited once.
enum ReadingSessionLedger {
    private struct State: Codable {
        var activeSession: ReadingSession?
        var minutesByDay: [String: Int] = [:]
        var hasPendingEndAnnouncement = false
    }

    private static let logger = Logger(subsystem: "Slumpy", category: "ReadingSessionLedger")

    static func begin(_ session: ReadingSession) {
        update { $0.activeSession = session }
    }

    static func discardActiveSession() {
        update { $0.activeSession = nil }
    }

    /// Credits the active session once its end time is reached.
    /// Returns the session that is still running, if any.
    static func finishIfDue(now: Date = .now, tolerance: TimeInterval = 0) -> ReadingSession? {
        update { state in
            if let session = state.activeSession, now.addingTimeInterval(tolerance) >= session.endDate {
                state.minutesByDay[dayKey(for: session.startDate), default: 0] += session.minutes
                state.activeSession = nil
                state.hasPendingEndAnnouncement = true
            }
            return state.activeSession
        }
    }

    static func consumeEndAnnouncement() -> Bool {
        update { state in
            let pending = state.hasPendingEndAnnouncement
            state.hasPendingEndAnnouncement = false
            return pending
        }
    }

    static func minutesRead(on day: Date) -> Int {
        withLock { load().minutesByDay[dayKey(for: day)] ?? 0 }
    }

    private static func update<T>(_ body: (inout State) -> T) -> T {
        withLock {
            var state = load()
            let result = body(&state)
            save(state)
            return result
        }
    }

    private static func withLock<T>(_ body: () -> T) -> T {
        let fd = open(containerURL.appendingPathComponent("reading-ledger.lock").path, O_CREAT | O_RDWR, 0o600)
        guard fd >= 0 else {
            logger.error("Cannot open ledger lock, errno \(errno)")
            return body()
        }
        defer { close(fd) }
        flock(fd, LOCK_EX)
        return body()
    }

    private static var containerURL: URL {
        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: AppGroup.id) else {
            fatalError("App Group \(AppGroup.id) is not enabled for this target")
        }
        return url
    }

    private static var ledgerURL: URL {
        containerURL.appendingPathComponent("reading-ledger.json")
    }

    private static func load() -> State {
        guard FileManager.default.fileExists(atPath: ledgerURL.path) else { return State() }
        do {
            return try JSONDecoder().decode(State.self, from: Data(contentsOf: ledgerURL))
        } catch {
            logger.error("Reading ledger is unreadable: \(error.localizedDescription, privacy: .public)")
            return State()
        }
    }

    private static func save(_ state: State) {
        do {
            // The extension usually runs while the phone is locked, so the file must stay writable then.
            try JSONEncoder().encode(state).write(
                to: ledgerURL,
                options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication]
            )
        } catch {
            logger.error("Cannot save reading ledger: \(error.localizedDescription, privacy: .public)")
        }
    }

    private static func dayKey(for date: Date) -> String {
        let day = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", day.year ?? 0, day.month ?? 0, day.day ?? 0)
    }
}
```

