final class DeviceActivityMonitorExtension: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard activity == .readingSession else { return }

        // The system can deliver the callback a little before the exact second of endDate.
        if ReadingSessionLedger.finishIfDue(tolerance: 120) == nil {
