### 4. Приложение: `ReadingSessionController.swift`

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation
import os

@MainActor
@Observable
final class ReadingSessionController {
    private(set) var activeSession: ReadingSession?
    private(set) var todayMinutes = 0
    private(set) var slumpyMessage: String?

    @ObservationIgnored private var endTimer: Task<Void, Never>?
    private let logger = Logger(subsystem: "Slumpy", category: "ReadingSession")

    func start(minutes: Int, blocking selection: FamilyActivitySelection) throws {
        refresh()
        guard activeSession == nil else { return }

        let now = Date.now
        let session = ReadingSession(
            id: UUID(),
            startDate: now,
            endDate: now.addingTimeInterval(TimeInterval(minutes * 60)),
            minutes: minutes
        )
        ReadingSessionLedger.begin(session)

        let store = ManagedSettingsStore(named: .readingSession)
        store.shield.applications = selection.applicationTokens
        store.shield.applicationCategories = .specific(selection.categoryTokens)
        store.shield.webDomains = selection.webDomainTokens

        do {
            // The system ends this interval even when the app is suspended or terminated;
            // the monitor extension then credits the minutes and lifts the shield.
            try DeviceActivityCenter().startMonitoring(.readingSession, during: schedule(from: now, to: session.endDate))
        } catch {
            store.clearAllSettings()
            ReadingSessionLedger.discardActiveSession()
            throw error
        }

        startLiveActivity(for: session)
        refresh()
    }

    /// Call whenever the app becomes active: finishes a session whose time ran out while the app was away.
    func refresh() {
        endTimer?.cancel()
        activeSession = ReadingSessionLedger.finishIfDue()

        if let session = activeSession {
            endTimer = Task { [weak self] in
                try? await Task.sleep(for: .seconds(session.endDate.timeIntervalSinceNow + 1))
                guard !Task.isCancelled else { return }
                self?.refresh()
            }
        } else {
            // Covers the case when the monitor extension did not run.
            ManagedSettingsStore(named: .readingSession).clearAllSettings()
            Task { await Self.endFinishedLiveActivities() }
        }

        todayMinutes = ReadingSessionLedger.minutesRead(on: .now)
        if ReadingSessionLedger.consumeEndAnnouncement() {
            slumpyMessage = "Сессия окончена"
        }
    }

    func dismissSlumpyMessage() {
        slumpyMessage = nil
    }

    private func schedule(from start: Date, to end: Date) -> DeviceActivitySchedule {
        let components: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        return DeviceActivitySchedule(
            intervalStart: Calendar.current.dateComponents(components, from: start),
            intervalEnd: Calendar.current.dateComponents(components, from: end),
            repeats: false
        )
    }

    private func startLiveActivity(for session: ReadingSession) {
        let attributes = ReadingSessionAttributes(startDate: session.startDate, endDate: session.endDate)
        // staleDate lets the widget switch to "session over" by itself, even if the app never runs again.
        let content = ActivityContent(state: ReadingSessionAttributes.ContentState(), staleDate: session.endDate)
        do {
            _ = try Activity.request(attributes: attributes, content: content)
        } catch {
            // The session works without a Live Activity, e.g. when the user turned them off.
            logger.error("Live Activity request failed: \(error.localizedDescription, privacy: .public)")
        }
    }

    // Only finished activities are ended, so a just-started session's activity is never caught by this.
    nonisolated private static func endFinishedLiveActivities() async {
        for activity in Activity<ReadingSessionAttributes>.activities where activity.attributes.endDate <= .now {
            await activity.end(nil, dismissalPolicy: .immediate)
        }
    }
}
```

