### 1. `ReadingSessionShared.swift` (приложение + Monitor-расширение)

```swift
import Foundation
import DeviceActivity
import ManagedSettings

// MARK: - Общие имена

extension DeviceActivityName {
    static var readingSession: Self { Self("slumpy.readingSession") }
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("slumpy.readingSession") }
}

// MARK: - Модель

struct ActiveReadingSession: Codable, Sendable, Equatable {
    var id: UUID
    var startDate: Date
    var endDate: Date
    var plannedMinutes: Int
}

struct CompletedReadingSession: Codable, Sendable, Equatable {
    var id: UUID
    var minutes: Int
    var endedAt: Date
}

struct ReadingState: Codable, Sendable {
    var activeSession: ActiveReadingSession?
    /// Прочитанные минуты по дням, ключ — "yyyy-MM-dd".
    var minutesByDay: [String: Int] = [:]
    /// Завершённая сессия, о которой Slumpy ещё не сказал.
    var pendingAnnouncement: CompletedReadingSession?
}

// MARK: - Хранилище в App Group

enum ReadingStore {
    /// ЗАМЕНИТЬ на ваш идентификатор App Group (тот же, что в Signing & Capabilities).
    static let appGroupID = "group.com.example.slumpy"

    private static var fileURL: URL? {
        FileManager.default
            .containerURL(forSecurityApplicationGroupIdentifier: appGroupID)?
            .appendingPathComponent("reading-state.json")
    }

    static func read() -> ReadingState {
        guard let url = fileURL else { return ReadingState() }
        var state = ReadingState()
        var error: NSError?
        NSFileCoordinator().coordinate(readingItemAt: url, options: [], error: &error) { url in
            state = load(from: url)
        }
        return state
    }

    /// Атомарное «прочитать → изменить → записать», безопасное между приложением и расширением.
    /// Возвращает nil, если App Group недоступна.
    @discardableResult
    static func update<T>(_ body: (inout ReadingState) -> T) -> T? {
        guard let url = fileURL else { return nil }
        var output: T?
        var error: NSError?
        NSFileCoordinator().coordinate(writingItemAt: url, options: .forMerging, error: &error) { url in
            var state = load(from: url)
            output = body(&state)
            save(state, to: url)
        }
        return output
    }

    static func dayKey(for date: Date, calendar: Calendar = .current) -> String {
        let c = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }

    private static func load(from url: URL) -> ReadingState {
        guard let data = try? Data(contentsOf: url),
              let state = try? JSONDecoder().decode(ReadingState.self, from: data)
        else { return ReadingState() }
        return state
    }

    private static func save(_ state: ReadingState, to url: URL) {
        guard let data = try? JSONEncoder().encode(state) else { return }
        // Файл должен быть доступен расширению, когда телефон заблокирован.
        try? data.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }
}

// MARK: - Завершение сессии (вызывают и расширение, и приложение)

enum SessionFinalizer {
    /// Допуск на случай, если система разбудит расширение чуть раньше конца.
    static let earlyTolerance: TimeInterval = 60

    /// Идемпотентно: минуты засчитываются один раз, сколько бы раз ни вызвали.
    @discardableResult
    static func finalizeIfDue(now: Date = .now) -> Bool {
        let finished = ReadingStore.update { state -> Bool in
            var didFinish = false
            // Проверка времени защищает от «ложных» вызовов intervalDidEnd
            // (например, когда сами останавливаем мониторинг перед новой сессией).
            if let session = state.activeSession,
               now >= session.endDate.addingTimeInterval(-earlyTolerance) {
                let day = ReadingStore.dayKey(for: session.startDate)
                state.minutesByDay[day, default: 0] += session.plannedMinutes
                state.pendingAnnouncement = CompletedReadingSession(
                    id: session.id,
                    minutes: session.plannedMinutes,
                    endedAt: session.endDate
                )
                state.activeSession = nil
                didFinish = true
            }
            if state.activeSession == nil {
                ManagedSettingsStore(named: .readingSession).clearAllSettings()
            }
            return didFinish
        }

        guard let finished else {
            // Хранилище недоступно: лучше разблокировать, чем оставить блокировку навсегда.
            ManagedSettingsStore(named: .readingSession).clearAllSettings()
            return false
        }
        return finished
    }
}
```

