### 3. `ReadingSessionManager.swift` (приложение)

```swift
import SwiftUI
import Observation
import ActivityKit
import DeviceActivity
import FamilyControls
import ManagedSettings

enum ReadingSessionError: LocalizedError {
    case alreadyRunning
    case tooShort
    case storageUnavailable
    case monitoringFailed

    var errorDescription: String? {
        switch self {
        case .alreadyRunning: "Сессия уже идёт."
        case .tooShort: "Сессия должна длиться не меньше 15 минут."
        case .storageUnavailable: "Не удалось сохранить сессию. Проверьте настройку App Group."
        case .monitoringFailed: "Не удалось запустить таймер сессии."
        }
    }
}

@MainActor
@Observable
final class ReadingSessionManager {
    private(set) var activeSession: ActiveReadingSession?
    private(set) var todayMinutes = 0
    /// Реплика для Slumpy. Когда она не nil, Slumpy должен её произнести.
    private(set) var slumpyMessage: String?

    @ObservationIgnored private var isInForeground = false
    @ObservationIgnored private var foregroundCheck: Task<Void, Never>?

    // MARK: Жизненный цикл

    func scenePhaseChanged(_ phase: ScenePhase) {
        isInForeground = (phase == .active)
        if isInForeground { refresh() }
    }

    func dismissSlumpyMessage() {
        slumpyMessage = nil
    }

    // MARK: Старт

    func start(minutes: Int = 30, selection: FamilyActivitySelection) throws {
        refresh() // доделать прошлую сессию, если она истекла
        guard activeSession == nil else { throw ReadingSessionError.alreadyRunning }
        // Apple не запускает расписания DeviceActivity короче 15 минут.
        guard minutes >= 15 else { throw ReadingSessionError.tooShort }

        let center = DeviceActivityCenter()
        center.stopMonitoring([.readingSession])

        let startDate = Date.now
        let endDate = startDate.addingTimeInterval(TimeInterval(minutes * 60))
        let session = ActiveReadingSession(
            id: UUID(),
            startDate: startDate,
            endDate: endDate,
            plannedMinutes: minutes
        )

        let saved = ReadingStore.update { state in
            state.activeSession = session
            let store = ManagedSettingsStore(named: .readingSession)
            store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
            store.shield.applicationCategories = selection.categoryTokens.isEmpty
                ? nil
                : .specific(selection.categoryTokens)
            store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
        }
        guard saved != nil else { throw ReadingSessionError.storageUnavailable }

        let calendar = Calendar.current
        let parts: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        let schedule = DeviceActivitySchedule(
            intervalStart: calendar.dateComponents(parts, from: startDate),
            intervalEnd: calendar.dateComponents(parts, from: endDate),
            repeats: false
        )

        do {
            try center.startMonitoring(.readingSession, during: schedule)
        } catch {
            ReadingStore.update { state in
                state.activeSession = nil
                ManagedSettingsStore(named: .readingSession).clearAllSettings()
            }
            throw ReadingSessionError.monitoringFailed
        }

        startLiveActivity(for: session)
        activeSession = session
        scheduleForegroundCheck(at: endDate)
    }

    // MARK: Проверка состояния (при открытии и в момент окончания)

    func refresh() {
        // Подстраховка: если расширение по какой-то причине не сработало, доделываем здесь.
        SessionFinalizer.finalizeIfDue()

        let state = ReadingStore.read()
        activeSession = state.activeSession
        todayMinutes = state.minutesByDay[ReadingStore.dayKey(for: .now)] ?? 0

        if let session = state.activeSession {
            scheduleForegroundCheck(at: session.endDate)
        } else {
            foregroundCheck?.cancel()
            foregroundCheck = nil
            endAllLiveActivities()
            let center = DeviceActivityCenter()
            if center.activities.contains(.readingSession) {
                center.stopMonitoring([.readingSession])
            }
        }

        if isInForeground, state.pendingAnnouncement != nil {
            ReadingStore.update { $0.pendingAnnouncement = nil }
            slumpyMessage = "Сессия окончена"
        }
    }

    // MARK: Таймер, пока приложение на экране

    private func scheduleForegroundCheck(at date: Date) {
        foregroundCheck?.cancel()
        foregroundCheck = Task { [weak self] in
            let delay = max(0, date.timeIntervalSinceNow) + 1
            try? await Task.sleep(for: .seconds(delay))
            guard !Task.isCancelled else { return }
            self?.refresh()
        }
    }

    // MARK: Live Activity

    private func startLiveActivity(for session: ActiveReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let content = ActivityContent(
            state: ReadingSessionAttributes.ContentState(
                startDate: session.startDate,
                endDate: session.endDate
            ),
            // В этот момент система сама перерисует карточку в «Сессия окончена».
            staleDate: session.endDate
        )
        _ = try? Activity<ReadingSessionAttributes>.request(
            attributes: ReadingSessionAttributes(plannedMinutes: session.plannedMinutes),
            content: content,
            pushType: nil
        )
    }

    private func endAllLiveActivities() {
        let activities = Activity<ReadingSessionAttributes>.activities
        guard !activities.isEmpty else { return }
        Task {
            for activity in activities {
                await activity.end(nil, dismissalPolicy: .immediate)
            }
        }
    }
}
```

