import SwiftUI

@main
struct SlumpyApp: App {
    @State private var readingSession = ReadingSessionManager()      // +
    @Environment(\.scenePhase) private var scenePhase                 // +

    var body: some Scene {
        WindowGroup {
            RootView()                                                // ваш корневой экран
                .environment(readingSession)                          // +
                .modifier(SlumpySessionAnnouncement())                // +
        }
        .onChange(of: scenePhase, initial: true) { _, phase in        // +
            readingSession.scenePhaseChanged(phase)                   // +
        }                                                             // +
    }
}

/// Показывает реплику Slumpy, когда сессия закончилась.
struct SlumpySessionAnnouncement: ViewModifier {
    @Environment(ReadingSessionManager.self) private var session

    func body(content: Content) -> some View {
        content.overlay(alignment: .bottom) {
            if let message = session.slumpyMessage {
                // ПОДКЛЮЧИТЬ: замените этот пузырь на вашего Slumpy, произносящего `message`.
                Text(message)
                    .font(.headline)
                    .padding()
                    .background(.thinMaterial, in: .capsule)
                    .padding(.bottom, 40)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .onTapGesture { session.dismissSlumpyMessage() }
                    .task(id: message) {
                        try? await Task.sleep(for: .seconds(5))
                        session.dismissSlumpyMessage()
                    }
            }
        }
        .animation(.spring, value: session.slumpyMessage)
    }
}
```

Кнопка старта на вашем экране вызывает `try readingSession.start(minutes: 30, selection: выбранныеПриложения)`. Сколько минут прочитано сегодня, берётся из `readingSession.todayMinutes`.

### 5. `ReadingMonitorExtension.swift` (Monitor-расширение)

В расширении может быть только один такой класс. Если он у вас уже есть, перенесите в него только метод `intervalDidEnd`.

```swift
import DeviceActivity
import Foundation

final class ReadingMonitorExtension: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard activity == .readingSession else { return }
        // Снимает блокировку, засчитывает минуты, оставляет пометку для Slumpy.
        SessionFinalizer.finalizeIfDue()
    }
}
```

