## Файл 1. `ReadingSessionShared.swift`
**Таргеты:** приложение + расширение DeviceActivityMonitor

```swift
import FamilyControls
import Foundation
import ManagedSettings

enum AppGroup {
    /// ← Замените на идентификатор вашего App Group.
    static let id = "group.com.example.slumpy"
}

// MARK: - Модель

struct ReadingSession: Codable, Sendable, Equatable {
    static let activityPrefix = "reading-session."

    let id: UUID
    let startDate: Date
    let endDate: Date

    var plannedMinutes: Int { Int((endDate.timeIntervalSince(startDate) / 60).rounded()) }
    var activityName: String { Self.activityPrefix + id.uuidString }

    static func id(fromActivityName name: String) -> UUID? {
        guard name.hasPrefix(activityPrefix) else { return nil }
        return UUID(uuidString: String(name.dropFirst(activityPrefix.count)))
    }
}

struct ReadingState: Codable, Sendable {
    var activeSession: ReadingSession?
    /// "2026-10-26" → минуты чтения за день.
    var minutesByDay: [String: Int] = [:]
    /// Slumpy должен сказать «Сессия окончена» при следующем показе приложения.
    var sessionEndedAnnouncementPending = false
}

// MARK: - Хранилище (общее для приложения и расширения)

enum ReadingStore {
    /// iOS может разбудить расширение с разбросом до минуты — считаем сессию законченной чуть раньше.
    static let endTolerance: TimeInterval = 60

    static func read() -> ReadingState {
        withLock { load() }
    }

    /// Атомарно читает, меняет и сохраняет состояние. Если `body` бросает ошибку, ничего не сохраняется.
    static func update<T>(_ body: (inout ReadingState) throws -> T) rethrows -> T {
        try withLock {
            var state = load()
            let result = try body(&state)
            save(state)
            return result
        }
    }

    /// Завершает сессию, если её время вышло: засчитывает минуты и ставит флаг для Slumpy.
    /// Идемпотентно — повторный вызов из приложения или расширения ничего не сделает.
    @discardableResult
    static func finishIfDue(_ state: inout ReadingState, sessionID: UUID? = nil, now: Date = .now) -> Bool {
        guard let session = state.activeSession,
              sessionID == nil || sessionID == session.id,
              now >= session.endDate.addingTimeInterval(-endTolerance)
        else { return false }

        state.minutesByDay[dayKey(session.startDate), default: 0] += session.plannedMinutes
        state.activeSession = nil
        state.sessionEndedAnnouncementPending = true
        return true
    }

    static func dayKey(_ date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }

    private static var containerURL: URL {
        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: AppGroup.id) else {
            fatalError("App Group \(AppGroup.id) не подключён к этому таргету")
        }
        return url
    }

    private static var stateURL: URL { containerURL.appendingPathComponent("reading-state.json") }
    private static var lockURL: URL { containerURL.appendingPathComponent("reading-state.lock") }

    /// Файловая блокировка работает между процессами: приложение и расширение не перезапишут друг друга.
    private static func withLock<T>(_ body: () throws -> T) rethrows -> T {
        let fd = open(lockURL.path, O_CREAT | O_RDWR, 0o644)
        guard fd >= 0 else { return try body() }
        flock(fd, LOCK_EX)
        defer {
            flock(fd, LOCK_UN)
            close(fd)
        }
        return try body()
    }

    private static func load() -> ReadingState {
        guard let data = try? Data(contentsOf: stateURL),
              let state = try? JSONDecoder().decode(ReadingState.self, from: data)
        else { return ReadingState() }
        return state
    }

    private static func save(_ state: ReadingState) {
        guard let data = try? JSONEncoder().encode(state) else { return }
        // Доступен при заблокированном экране (после первой разблокировки) — расширение часто срабатывает именно так.
        try? data.write(to: stateURL, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }
}

// MARK: - Блокировка приложений

extension ManagedSettingsStore.Name {
    static let readingSession = Self(rawValue: "readingSession")
}

enum ReadingShield {
    static func apply(_ selection: FamilyActivitySelection) {
        let store = ManagedSettingsStore(named: .readingSession)
        let apps = selection.applicationTokens
        let categories = selection.categoryTokens
        let domains = selection.webDomainTokens
        store.shield.applications = apps.isEmpty ? nil : apps
        store.shield.applicationCategories = categories.isEmpty ? nil : .specific(categories)
        store.shield.webDomains = domains.isEmpty ? nil : domains
        store.shield.webDomainCategories = categories.isEmpty ? nil : .specific(categories)
    }

    static func remove() {
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }
}
```

