## Файл 3. `ReadingMonitorExtension.swift`
**Таргет:** расширение DeviceActivityMonitor

```swift
import DeviceActivity
import Foundation

/// Если в расширении уже есть класс-наследник DeviceActivityMonitor,
/// перенесите тело `intervalDidEnd` в него, а этот класс удалите.
final class ReadingMonitorExtension: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingSession.id(fromActivityName: activity.rawValue) else { return }

        ReadingStore.update { state in
            ReadingStore.finishIfDue(&state, sessionID: sessionID)
            // Снимаем блокировку, только если чтение не идёт.
            // Если пользователь уже начал новую сессию, её блокировку не трогаем.
            if state.activeSession == nil {
                ReadingShield.remove()
            }
        }
    }
}
```

