## Файл 4. `ReadingSessionManager.swift`
**Таргет:** приложение

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import Observation
import SwiftUI

@MainActor
@Observable
final class ReadingSessionManager {
    static let shared = ReadingSessionManager()
    static let sessionEndedLine = "Сессия окончена"

    enum StartError: Error {
        case alreadyRunning
        case tooShort
    }

    private(set) var activeSession: ReadingSession?
    /// Прогресс дневной цели (минуты чтения за сегодня).
    private(set) var todayMinutes = 0
    /// Фраза, которую должен сказать Slumpy. После показа вызывается `slumpyDidSpeak()`.
    private(set) var slumpyLine: String?

    @ObservationIgnored private var endTimer: Task<Void, Never>?

    private init() {}

    // MARK: Публичные действия

    /// Запускает сессию: блокирует выбранные приложения, ставит будильник для расширения, показывает Live Activity.
    func start(minutes: Int = 30, blocking selection: FamilyActivitySelection) throws {
        // iOS не запускает DeviceActivity-расписания короче 15 минут.
        guard minutes >= 15 else { throw StartError.tooShort }

        let now = Date.now
        let session = ReadingSession(
            id: UUID(),
            startDate: now,
            endDate: now.addingTimeInterval(TimeInterval(minutes * 60))
        )

        try ReadingStore.update { state in
            guard state.activeSession == nil else { throw StartError.alreadyRunning }
            try Self.startMonitoring(session)
            state.activeSession = session
            ReadingShield.apply(selection)
        }

        ReadingLiveActivity.start(for: session)
        refresh()
    }

    /// Досрочная остановка: засчитываются реально прочитанные полные минуты, Slumpy ничего не говорит.
    func cancel() {
        ReadingStore.update { state in
            guard let session = state.activeSession else { return }
            let elapsed = max(0, Int(Date.now.timeIntervalSince(session.startDate) / 60))
            state.minutesByDay[ReadingStore.dayKey(session.startDate), default: 0] += elapsed
            state.activeSession = nil
            ReadingShield.remove()
        }
        refresh()
    }

    /// Сверяет состояние с реальностью. Вызывается при каждом открытии приложения и по таймеру конца сессии.
    func refresh() {
        let now = Date.now
        let state = ReadingStore.update { state in
            ReadingStore.finishIfDue(&state, now: now)
            // Страховка на случай, если расширение не сработало.
            if state.activeSession == nil {
                ReadingShield.remove()
            }
            return state
        }

        activeSession = state.activeSession
        todayMinutes = state.minutesByDay[ReadingStore.dayKey(now), default: 0]
        if state.sessionEndedAnnouncementPending {
            slumpyLine = Self.sessionEndedLine
        }

        Self.stopStaleMonitors(keeping: state.activeSession)
        Task { await ReadingLiveActivity.endFinished() }
        scheduleEndTimer(for: state.activeSession)
    }

    func slumpyDidSpeak() {
        slumpyLine = nil
        ReadingStore.update { $0.sessionEndedAnnouncementPending = false }
    }

    func minutes(on date: Date) -> Int {
        ReadingStore.read().minutesByDay[ReadingStore.dayKey(date), default: 0]
    }

    // MARK: Внутреннее

    /// Работает, только пока приложение открыто. В фоне сессию закроет расширение.
    private func scheduleEndTimer(for session: ReadingSession?) {
        endTimer?.cancel()
        guard let session else { return }
        endTimer = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, session.endDate.timeIntervalSinceNow) + 1))
            guard !Task.isCancelled else { return }
            self?.refresh()
        }
    }

    nonisolated private static func startMonitoring(_ session: ReadingSession) throws {
        let calendar = Calendar.current
        let components: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        let schedule = DeviceActivitySchedule(
            intervalStart: calendar.dateComponents(components, from: session.startDate),
            intervalEnd: calendar.dateComponents(components, from: session.endDate),
            repeats: false
        )
        try DeviceActivityCenter().startMonitoring(DeviceActivityName(rawValue: session.activityName), during: schedule)
    }

    nonisolated private static func stopStaleMonitors(keeping session: ReadingSession?) {
        let center = DeviceActivityCenter()
        let stale = center.activities.filter {
            $0.rawValue.hasPrefix(ReadingSession.activityPrefix) && $0.rawValue != session?.activityName
        }
        if !stale.isEmpty {
            center.stopMonitoring(stale)
        }
    }
}

// MARK: - Live Activity

enum ReadingLiveActivity {
    static func start(for session: ReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let attributes = ReadingSessionAttributes(
            sessionID: session.id,
            startDate: session.startDate,
            endDate: session.endDate
        )
        // staleDate: в момент окончания виджет сам переключится на «Сессия окончена», даже если приложение выгружено.
        let content = ActivityContent(state: ReadingSessionAttributes.ContentState(isFinished: false), staleDate: session.endDate)
        _ = try? Activity<ReadingSessionAttributes>.request(attributes: attributes, content: content, pushType: nil)
    }

    /// Убирает все Live Activity чтения, кроме той, что относится к идущей сессии.
    static func endFinished() async {
        let activeID = ReadingStore.read().activeSession?.id
        let finalContent = ActivityContent(state: ReadingSessionAttributes.ContentState(isFinished: true), staleDate: nil)
        for activity in Activity<ReadingSessionAttributes>.activities where activity.attributes.sessionID != activeID {
            await activity.end(finalContent, dismissalPolicy: .immediate)
        }
    }
}

// MARK: - Подключение к интерфейсу

struct ReadingSessionLifecycle: ViewModifier {
    @Environment(\.scenePhase) private var scenePhase
    private let manager = ReadingSessionManager.shared
    let onSlumpyLine: (String) -> Void

    func body(content: Content) -> some View {
        content
            .onChange(of: scenePhase, initial: true) { _, phase in
                if phase == .active {
                    manager.refresh()
                }
            }
            .onChange(of: manager.slumpyLine, initial: true) { _, line in
                guard let line else { return }
                onSlumpyLine(line)
                manager.slumpyDidSpeak()
            }
    }
}

extension View {
    /// Повесьте на корневой экран приложения. В замыкании заставьте Slumpy произнести фразу.
    func readingSessionLifecycle(onSlumpyLine: @escaping (String) -> Void) -> some View {
        modifier(ReadingSessionLifecycle(onSlumpyLine: onSlumpyLine))
    }
}
```

