import ActivityKit
import SwiftUI
import WidgetKit

struct ReadingSessionLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: ReadingSessionAttributes.self) { context in
            ReadingLockScreenView(context: context)
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.leading) {
                    ReadingIcon(context: context).font(.title2)
                }
                DynamicIslandExpandedRegion(.trailing) {
                    ReadingTimerText(context: context).font(.title2)
                }
                DynamicIslandExpandedRegion(.bottom) {
                    if context.isSessionFinished {
                        Text("Сессия окончена").font(.headline)
                    } else {
                        ReadingProgressBar(context: context)
                    }
                }
            } compactLeading: {
                ReadingIcon(context: context)
            } compactTrailing: {
                ReadingTimerText(context: context).frame(maxWidth: 44)
            } minimal: {
                ReadingIcon(context: context)
            }
        }
    }
}

private extension ActivityViewContext<ReadingSessionAttributes> {
    /// isStale становится true автоматически в момент окончания сессии (staleDate).
    var isSessionFinished: Bool { isStale || state.isFinished }
    var sessionRange: ClosedRange<Date> { attributes.startDate...attributes.endDate }
}

private struct ReadingLockScreenView: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        HStack(spacing: 12) {
            ReadingIcon(context: context).font(.title2)
            VStack(alignment: .leading, spacing: 6) {
                Text(context.isSessionFinished ? "Сессия окончена" : "Читаем").font(.headline)
                if !context.isSessionFinished {
                    ReadingProgressBar(context: context)
                }
            }
            Spacer()
            ReadingTimerText(context: context).font(.title2)
        }
        .padding()
    }
}

private struct ReadingIcon: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        Image(systemName: context.isSessionFinished ? "checkmark.circle.fill" : "book.fill")
    }
}

private struct ReadingTimerText: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        if context.isSessionFinished {
            Text("0:00").monospacedDigit()
        } else {
            // Система сама обновляет обратный отсчёт; на нуле он останавливается.
            Text(timerInterval: context.sessionRange, countsDown: true)
                .monospacedDigit()
                .multilineTextAlignment(.trailing)
        }
    }
}

private struct ReadingProgressBar: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        ProgressView(timerInterval: context.sessionRange, countsDown: false) {
            EmptyView()
        } currentValueLabel: {
            EmptyView()
        }
    }
}
